import React from "react";

const Results = ({ data }) => (
  <div className="card">
    <h2>Meeting Summary</h2>
    <p>{data.summary}</p>

    <h3>MOM</h3>
    {Array.isArray(data.mom) ? (
      <ul>
        {data.mom.map((item, i) => (
          <li key={i}>{item}</li>
        ))}
      </ul>
    ) : (
      <p>{data.mom}</p>
    )}

    <h3>Tasks</h3>
    <ul>
      {data.tasks?.map((t, i) => (
        <li key={i}>
          {typeof t === "object" ? `${t.task || JSON.stringify(t)} - ${t.date || "No date"}` : t}
        </li>
      ))}
    </ul>

    {data.important_dates && data.important_dates.length > 0 && (
      <>
        <h3>Important Dates</h3>
        <ul>
          {data.important_dates.map((date, i) => (
            <li key={i}>{date}</li>
          ))}
        </ul>
      </>
    )}
  </div>
);

export default Results;
